"""Private562: the MeloNX keyboard and L3/R3 files (9b40129, their own iPhone host run) on the delivered 561 product tree.

562 ships the 561 product (the RPCS3 Core 561, the 558 MeloNX engine, every
other shipped file) and changes only the MeloNX host: three Swift files and
the twelve-language strings compiled into it. The 561 recipe therefore runs
unchanged on the delivered 561 tree, which as_561() puts in place of the
pinned 562 one for the duration of each inherited check (a scratch index, the
562 files' 561 versions in the working tree, the controller strings
generated from them and BUILD_NUMBER 561, all restored afterwards); the 561
recipe puts the 560, 559 and 558 trees back for its own inherited checks in
turn. The 562 host evidence (its host run: iPhone SDK typecheck, native ABI
double, UIKit presentation, perf journal, parity and the UIKit keyboard
probe) is checked on the pinned 562 tree.
"""
import argparse,contextlib,hashlib,json,os,sys,tempfile
from pathlib import Path
import melonxinput562_tree as tree
import rpcs3cell561_delivery as d561
ROOT=Path(__file__).resolve().parents[2]
BUILD='562'
HOST_TREE=d561.HOST_TREE
# The engine, the RPCS3 Core 561 and every other shipped file are the 561 ones.
for name in ('MELONX_SOURCE','MELONX_RUN','MELONX_ARTIFACT','HOST_SOURCE','HOST_RUN','HOST_ARTIFACT',
             'HOST_SOURCE553','HOST_RUN553','HOST_ARTIFACT553','ENGINE_STEPS','HOST_STEPS558','GRAPH_STEP',
             'command','at','shipped_interface','CORE_SOURCE','CORE_RUN','CORE560_SOURCE','CORE560_RUN',
             'CORE559_SOURCE','CORE559_RUN','CORE551_SOURCE','CORE551_RUN','validate_rpc_core_identity',
             'validate_rpc_core_pin','core_receipt','core_run'):
 globals()[name]=getattr(d561,name)
previous,previous546,d549,d557,d558,d559=d561.previous,d561.previous546,d561.d549,d561.d557,d561.d558,d561.d559
d560=d561.d560
# iPhone host built and tested from 9b40129 (every Swift file of this tree),
# with the UIKit keyboard probe on macOS, taken by ID and digest.
HOST562_SOURCE=tree.SOURCE562
HOST562_RUN=40484359276
HOST562_ARTIFACT=(12724972766,'3f1914d65c776a5a9205fde092db2d48207c774598d4d7bfe6e3d1fb8a0d019b')
HOST562_WORKFLOW='.github/workflows/melonx-host.yml'
KEYBOARD_STEP='Answer the Switch keyboard in UIKit and check the L3/R3 toggle wiring'
HOST_STEPS562=HOST_STEPS558+[KEYBOARD_STEP]
SHIPPED562=set(tree.SHIPPED562)
PROBE_CHECKS=19
# Generated by vendor_controller.py from ui-strings.json (562 adds two rows):
# hashed by the 558 and 562 host runs, so each view carries its own.
STRINGS=ROOT/'packages/melonx_internal_bridge/ios/Controller/MeloNXStrings.swift'

_active=[False]

@contextlib.contextmanager
def as_561():
 """The delivered 561 tree in place of the pinned 562 one: a scratch copy of
 the index with the 562 files at their 561 versions and this recipe removed,
 the same 562 files in the working tree, the controller strings generated
 from them, and build number 561. The 562 bytes, the index in use and the
 environment are restored on exit; a check already inside the 561 view stays
 in it."""
 if _active[0]:
  yield
  return
 versions=tree.at_561()
 files={p:s for p,s in versions.items() if p in tree.FIX562}
 saved={p:(ROOT/p).read_bytes() if (ROOT/p).is_file() else None for p in files}
 strings=STRINGS.read_bytes() if STRINGS.is_file() else None
 env={k:os.environ.get(k) for k in ('GIT_INDEX_FILE','BUILD_NUMBER')}
 with tempfile.TemporaryDirectory() as scratch:
  index=os.path.join(scratch,'index')
  tree.index_with(versions,index)
  try:
   for p,source in files.items():
    target=ROOT/p
    if source is None:target.unlink(missing_ok=True)
    else:target.parent.mkdir(parents=True,exist_ok=True);target.write_bytes(at(source,p))
   if strings is not None:
    sys.path.insert(0,str(ROOT/'build-utils/melonx'))
    from generate_ui_strings import generate
    generate(ROOT,STRINGS)
   os.environ['GIT_INDEX_FILE']=index;os.environ['BUILD_NUMBER']=d561.BUILD
   _active[0]=True
   yield
  finally:
   _active[0]=False
   for k,v in env.items():
    if v is None:os.environ.pop(k,None)
    else:os.environ[k]=v
   for p,data in saved.items():
    if data is None:(ROOT/p).unlink(missing_ok=True)
    else:(ROOT/p).parent.mkdir(parents=True,exist_ok=True);(ROOT/p).write_bytes(data)
   if strings is not None:STRINGS.write_bytes(strings)
 # Nothing of the 561 view may leak into the pinned tree.
 for p,data in saved.items():
  assert ((ROOT/p).read_bytes() if (ROOT/p).is_file() else None)==data,p
 assert (STRINGS.read_bytes() if STRINGS.is_file() else None)==strings
 assert 'GIT_INDEX_FILE' not in os.environ or os.environ['GIT_INDEX_FILE']==env['GIT_INDEX_FILE']

def inherited(function,*args,**kwargs):
 """A check of the 561 recipe, run on the delivered 561 tree."""
 with as_561():return function(*args,**kwargs)

@contextlib.contextmanager
def as_558():
 """The delivered 558 tree, through the 561 view (for the validators of 558 receipts)."""
 with as_561(),d561.as_558():yield

def validate_interface():
 return inherited(d561.validate_interface)

def sha(p):
 return hashlib.sha256((ROOT/p).read_bytes()).hexdigest()

def source_contract():
 assert os.environ['BUILD_NUMBER']==BUILD and os.environ.get('GITHUB_REF_NAME','Claude')=='Claude'
 head=command('git','rev-parse','HEAD');assert os.environ['GITHUB_SHA']==head
 tree.parent_contract()
 kept=tree.verify()
 # The 561 contract, unchanged, on the delivered 561 tree.
 report=inherited(d561.source_contract)
 assert report['productTrees']==tree.product_trees_561(),report['productTrees']
 trees=tree.product_trees()
 assert {p for p in tree.TREES if trees[p]!=report['productTrees'][p]}=={'packages'},trees
 # The pinned index differs from the delivered 561 tree by the 562 files and this recipe only.
 versions=tree.at_561()
 changed=set(command('git','diff','--cached','--name-only',tree.tree_561()).splitlines())
 # Documentation an earlier recipe owns follows HEAD in both trees, so it cannot differ.
 expected={p for p in set(tree.FIX562)|set(tree.RECIPE) if versions[p]!=head}
 assert changed==expected,changed^expected
 for p in tree.FIX562:
  if tree.source_of(p):assert (ROOT/p).read_bytes()==at(HOST562_SOURCE,p),p
 # The RPCS3 Core 561, unchanged, on the pinned tree.
 d561.native.source_contract()
 for p,h in d561.native.inputs().items():assert hashlib.sha256(at(CORE_SOURCE,p)).hexdigest()==h,p
 if d561.INSTALLED.exists():validate_rpc_core_identity(json.loads(d561.INSTALLED.read_bytes()))
 return dict(report,build=int(BUILD),source=head,build561=report['build'],source561Recipe=report['source'],
  source562=HOST562_SOURCE,host562Source=HOST562_SOURCE,host562Run=HOST562_RUN,host562Artifact=HOST562_ARTIFACT[0],
  replaced562=tree.REPLACED,changed562=sorted(changed),shipped562=sorted(SHIPPED562),pinnedFiles=kept,
  productTrees=trees,productTrees561=report['productTrees'],physicalDeviceTested=False,gameTested=False)

def host_run():
 """The 562 host run: the exact commit, its own workflow, every host step and the keyboard probe passed."""
 state=previous.api(f'actions/runs/{HOST562_RUN}')
 assert state['head_sha']==HOST562_SOURCE and state['path']==HOST562_WORKFLOW,(state['head_sha'],state['path'])
 return previous.completed(HOST562_RUN,HOST562_SOURCE,HOST_STEPS562)

def host_evidence():
 """The downloaded 562 host proofs name exactly the pinned Swift files: the
 iPhone SDK typecheck and native ABI double, the UIKit presentation, and the
 keyboard probe with the pinned MeloNX and Melo-Controller sources."""
 base=ROOT/'dist/melonx-host562'
 checks=json.loads((base/'checks.json').read_bytes())
 assert checks['source']==HOST562_SOURCE and checks['iphoneSDKTypecheck'] and checks['nativeABIDouble']
 for p in SHIPPED562:assert checks['inputs'][p]==sha(p),p
 presentation=json.loads((base/'presentation.json').read_bytes())
 assert presentation['result']=='passed' and presentation['source']==HOST562_SOURCE
 keyboard=json.loads((base/'text-input.json').read_bytes())
 assert keyboard['result']=='passed' and keyboard['engineProtocolChecked'] and keyboard['controllerSourceChecked']
 probe=keyboard['uikitProbe']
 assert probe['result']=='passed' and probe['checks']==PROBE_CHECKS,probe.get('error')
 assert keyboard['physicalDeviceTested'] is False and keyboard['gameTested'] is False
 # Every input, the generated controller sources included, is this tree's.
 for receipt in (checks,presentation,keyboard):
  for p,h in receipt['inputs'].items():assert sha(p)==h,p
 assert set(tree.FIX562)-{p for p in tree.FIX562 if p.startswith('docs/')}<=set(checks['inputs'])|set(keyboard['inputs'])
 answers=[a['name'].rsplit('_',1)[-1] for a in probe['answers']]
 assert answers==['a1','a2','q1','q2','m1','late'],answers
 return dict(source=HOST562_SOURCE,run=HOST562_RUN,keyboardChecks=keyboard['checks'],probeChecks=probe['checks'],
  answers=probe['answers'],iphoneSDKTypecheck=True,nativeABIDouble=True,physicalDeviceTested=False,gameTested=False)

def retain_checks():
 """The 561 receipts stay bound to the delivered 561 tree (and its 560, 559 and 558 views); the 562 host run to the pinned tree."""
 inherited(d561.retain_checks)
 out=ROOT/'build/delivery';out.mkdir(parents=True,exist_ok=True)
 (out/'melonx-input562-host-run.json').write_text(json.dumps(host_run(),indent=2)+'\n')
 print('Bound the 561 receipts to the delivered 561 tree and the 562 host run to the pinned tree.')

def main():
 p=argparse.ArgumentParser();p.add_argument('--rpc-core-inputs');p.add_argument('core_paths',nargs='*')
 p.add_argument('--retain-checks',action='store_true');p.add_argument('--wait-for-components',action='store_true')
 p.add_argument('--source-only',action='store_true');p.add_argument('--skin-session-evidence',action='store_true');p.add_argument('--scope')
 p.add_argument('--logger-proofs',action='store_true');p.add_argument('--download-components',action='store_true')
 p.add_argument('--engine-evidence',action='store_true')
 p.add_argument('--output',default='build/delivery/reused-validation562.json');a=p.parse_args()
 if a.rpc_core_inputs:validate_rpc_core_pin(a.rpc_core_inputs,a.core_paths);return
 report=source_contract()
 if a.retain_checks:retain_checks()
 if a.logger_proofs:
  # The 561 binding on the delivered 561 tree (its own views in turn), then the pinned tree.
  inherited(d561.inherited,d560.inherited,d559.inherited,d558.inherited,d557.inherited,previous546.logger_proofs)
  inherited(d561.inherited,d560.inherited,previous546.logger_proofs)
  inherited(d561.inherited,previous546.logger_proofs)
  inherited(previous546.logger_proofs);previous546.logger_proofs()
  print('Bound the 536 retention and 546 logger runs of this job to the current sources.');return
 if a.download_components:
  report['downloads']=[d549.download(MELONX_ARTIFACT,'dist/melonx'),d549.download(HOST_ARTIFACT,'dist/melonx-host'),
                       d549.download(HOST_ARTIFACT553,'dist/melonx-host553'),d549.download(HOST562_ARTIFACT,'dist/melonx-host562')]
 if a.engine_evidence:
  report['engineEvidence']=inherited(d558.engine_evidence)
  report['host562Evidence']=host_evidence()
 if a.wait_for_components:report['rpcCore']=core_run()
 if a.skin_session_evidence:
  report['engine']=previous.completed(MELONX_RUN,MELONX_SOURCE,ENGINE_STEPS)
  report['host']=previous.completed(HOST_RUN,HOST_SOURCE,HOST_STEPS558)
  report['graph']=previous.completed(HOST_RUN553,HOST_SOURCE553,[GRAPH_STEP])
  report['host562']=host_run()
 if not a.source_only:
  out=ROOT/a.output;out.parent.mkdir(parents=True,exist_ok=True);out.write_text(json.dumps(report,indent=2)+'\n')
 print(json.dumps(report,indent=2))
if __name__=='__main__':main()
